from openpyxl import load_workbook

wb = load_workbook('gdp.xlsx')
task = wb['Task']

print("Merged cells:", task.merged_cells.ranges)

print("\nSearching for cells with fill color...")
for row in task.iter_rows(min_row=1, max_row=15, min_col=1, max_col=15):
    for cell in row:
        if cell.fill and cell.fill.start_color and cell.fill.start_color.rgb:
            color = cell.fill.start_color.rgb
            # Ignore None or white (FFFFFFFF or 00000000 if not set)
            if color not in ['00000000', 'FFFFFFFF', None]:
                 print(f"Cell {cell.coordinate}: Value='{cell.value}', Color={color}")

print("\nSpecific check for H10-L10:")
for col in range(8, 13):
    cell = task.cell(row=10, column=col)
    print(f"Cell {cell.coordinate}: Value={cell.value}, Fill={cell.fill.start_color.rgb if cell.fill else 'None'}")

